/**
 * Passkey signing for Constella smart accounts - a line-for-line port of
 * services/relayer/src/constella_relayer/passkey.py (proven on a real local
 * network), checked against vectors generated by that Python code
 * (test/passkey.test.ts). The browser computes EVERYTHING the user signs:
 * nothing about the payload is trusted from the relayer.
 *
 *  1. payload   = SHA-256(HashIdPreimage) of the auth entry (stellar-sdk's
 *                 buildAuthorizationEntryPreimage handles legacy ADDRESS and
 *                 CAP-71 ADDRESS_V2, which binds the address).
 *  2. challenge = SHA-256(XDR(AuthDigestPreimage{account, context_rule_ids,
 *                 signature_payload})), one rule id per authorized context.
 *  3. WebAuthn assertion (UP + UV) -> DER signature -> 64-byte low-S r||s.
 *  4. credential signature = AuthPayload{context_rule_ids, signers:
 *     {Signer::External(verifier, pubkey): XDR(WebAuthnSigData)}}.
 */
import { Address, buildAuthorizationEntryPreimage, hash, xdr } from "@stellar/stellar-sdk";

const P256_N = 0xffffffff00000000ffffffffffffffffbce6faada7179e84f3b9cac2fc632551n;

export function struct(fields: Record<string, xdr.ScVal>): xdr.ScVal {
  // #[contracttype] struct: map keyed by field-name symbols, SORTED.
  return xdr.ScVal.scvMap(Object.keys(fields).sort().map((k) => new xdr.ScMapEntry({ key: xdr.ScVal.scvSymbol(k), val: fields[k] })));
}

const u32Vec = (ids: number[]) => xdr.ScVal.scvVec(ids.map((i) => xdr.ScVal.scvU32(i)));
const bytes = (b: Uint8Array) => xdr.ScVal.scvBytes(b as any);
// No Node Buffer in the browser bundle (Vite does not polyfill it).
const toHex = (b: Uint8Array) => Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
const fromHex = (h: string) => Uint8Array.from(h.match(/../g)!.map((x) => parseInt(x, 16)));

export function authDigest(account: string, payload: Uint8Array, ruleIds: number[]): Uint8Array {
  const pre = struct({
    account: new Address(account).toScVal(),
    context_rule_ids: u32Vec(ruleIds),
    signature_payload: bytes(payload),
  });
  return new Uint8Array(hash(pre.toXDR()));
}

// stellar-sdk 17.4 XDR objects are immutable with property access: build new
// credentials / entries instead of mutating (as the SDK's own auth.js does).
const X = xdr as any;

export function countInvocations(inv: any): number {
  return 1 + inv.subInvocations.reduce((n: number, s: any) => n + countInvocations(s), 0);
}

function addressCreds(entry: any): any {
  const c = entry.credentials;
  switch (c.type) {
    case "sorobanCredentialsAddress": return c.address;
    case "sorobanCredentialsAddressV2": return c.addressV2;
    default: throw new Error(`a passkey can only sign address credentials, not ${c.type}`);
  }
}

function withCreds(entry: any, old: any, validUntil: number, signature: xdr.ScVal): any {
  const creds = new X.SorobanAddressCredentials({ address: old.address, nonce: old.nonce, signatureExpirationLedger: validUntil, signature });
  const wrapped = entry.credentials.type === "sorobanCredentialsAddressV2"
    ? X.SorobanCredentials.sorobanCredentialsAddressV2(creds)
    : X.SorobanCredentials.sorobanCredentialsAddress(creds);
  return new X.SorobanAuthorizationEntry({ credentials: wrapped, rootInvocation: entry.rootInvocation });
}

/** (payload, challenge, ruleIds) for an entry - what the passkey must sign. */
export function signingInput(entryXdr: string, validUntil: number, passphrase: string, ruleId: number) {
  const entry: any = xdr.SorobanAuthorizationEntry.fromXDR(entryXdr, "base64");
  const creds = addressCreds(entry);
  const account = Address.fromScAddress(creds.address).toString();
  const preimage = buildAuthorizationEntryPreimage(entry, validUntil, passphrase);
  const payload = new Uint8Array(hash(preimage.toXDR()));
  const ruleIds: number[] = Array(countInvocations(entry.rootInvocation)).fill(ruleId);
  return { entry, creds, validUntil, account, payload, ruleIds, challenge: authDigest(account, payload, ruleIds) };
}

/** DER ECDSA signature -> 64-byte r||s with low S (the verifier's rule). */
export function derToLowS(der: Uint8Array): Uint8Array {
  let i = 2;
  const read = () => { if (der[i++] !== 0x02) throw new Error("bad DER"); const len = der[i++]; const v = der.slice(i, i + len); i += len; return v; };
  const toBig = (b: Uint8Array) => BigInt("0x" + toHex(b));
  const r = toBig(read());
  let s = toBig(read());
  if (s > P256_N / 2n) s = P256_N - s;
  const hex = (n: bigint) => n.toString(16).padStart(64, "0");
  return fromHex(hex(r) + hex(s));
}

export interface Assertion { authenticatorData: Uint8Array; clientDataJSON: Uint8Array; signature: Uint8Array /* DER */ }

/** Fill the entry's credentials with a passkey signature; returns base64 XDR. */
export function attachSignature(input: ReturnType<typeof signingInput>, verifier: string, publicKey: Uint8Array, a: Assertion): string {
  const sigData = struct({
    authenticator_data: bytes(a.authenticatorData),
    client_data: bytes(a.clientDataJSON),
    signature: bytes(derToLowS(a.signature)),
  });
  const signer = xdr.ScVal.scvVec([xdr.ScVal.scvSymbol("External"), new Address(verifier).toScVal(), bytes(publicKey)]);
  const signers = xdr.ScVal.scvMap([new xdr.ScMapEntry({ key: signer, val: bytes(new Uint8Array(sigData.toXDR())) })]);
  const signed = withCreds(input.entry, input.creds, input.validUntil, struct({ context_rule_ids: u32Vec(input.ruleIds), signers }));
  return signed.toXDR("base64");
}

// ----------------------------------------------------------- WebAuthn (browser)
const b64u = (b: Uint8Array) => btoa(String.fromCharCode(...b)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

export type Where = "platform" | "cross-platform";

/** Register a passkey on THIS device (Windows Hello / Touch ID) or on a phone
 * / security key. Returns its id, 65-byte uncompressed P-256 key, where it
 * lives and its transports (so signing asks only that authenticator). */
export async function createPasskey(name: string, where: Where = "platform"):
    Promise<{ id: string; publicKey: Uint8Array; attachment: string; transports: string[] }> {
  const cred = (await navigator.credentials.create({
    publicKey: {
      challenge: crypto.getRandomValues(new Uint8Array(32)),
      rp: { name: "Constella sandbox", id: location.hostname },
      user: { id: crypto.getRandomValues(new Uint8Array(16)), name, displayName: name },
      pubKeyCredParams: [{ type: "public-key", alg: -7 }], // ES256 = P-256
      authenticatorSelection: { userVerification: "required", residentKey: "preferred", authenticatorAttachment: where },
    },
  })) as PublicKeyCredential;
  const resp = cred.response as AuthenticatorAttestationResponse;
  const spki = new Uint8Array(resp.getPublicKey()!); // SubjectPublicKeyInfo: last 65 bytes = 0x04||X||Y
  const publicKey = spki.slice(spki.length - 65);
  if (publicKey[0] !== 0x04) throw new Error("unexpected public key format");
  const transports = typeof resp.getTransports === "function" ? resp.getTransports() : [];
  return { id: b64u(new Uint8Array(cred.rawId)), publicKey, attachment: (cred as any).authenticatorAttachment ?? where, transports };
}

/** Ask the passkey to sign `challenge` (user present + verified). */
export async function getAssertion(credentialId: string, challenge: Uint8Array, transports: string[] = []): Promise<Assertion> {
  const raw = Uint8Array.from(atob(credentialId.replace(/-/g, "+").replace(/_/g, "/")), (c) => c.charCodeAt(0));
  // Transports recorded at creation route the request to the RIGHT device
  // (e.g. "internal" = Windows Hello, no phone QR code).
  const allow: any = { type: "public-key", id: raw };
  if (transports.length) allow.transports = transports;
  const cred = (await navigator.credentials.get({
    publicKey: { challenge, allowCredentials: [allow], userVerification: "required", rpId: location.hostname },
  })) as PublicKeyCredential;
  const r = cred.response as AuthenticatorAssertionResponse;
  return { authenticatorData: new Uint8Array(r.authenticatorData), clientDataJSON: new Uint8Array(r.clientDataJSON), signature: new Uint8Array(r.signature) };
}

// ------------------------------------------- test passkey (LOCAL testing only)
// A P-256 key held by this browser (WebCrypto) that produces exactly the
// WebAuthn assertion a platform authenticator would: authenticatorData =
// SHA-256(rpId) || flags(UP|UV) || counter; clientDataJSON with the challenge;
// signature over authenticatorData || SHA-256(clientDataJSON). For testing
// when no usable authenticator exists (e.g. phones refuse 'localhost'
// passkeys). The real product uses real passkeys only.

/** WebCrypto signs in raw r||s (P1363); attachSignature expects DER. */
export function rawToDer(raw: Uint8Array): Uint8Array {
  const int = (b: Uint8Array) => {
    let i = 0;
    while (i < b.length - 1 && b[i] === 0) i++;
    let v = b.slice(i);
    if (v[0] & 0x80) v = new Uint8Array([0, ...v]);
    return new Uint8Array([0x02, v.length, ...v]);
  };
  const r = int(raw.slice(0, 32)), s = int(raw.slice(32));
  return new Uint8Array([0x30, r.length + s.length, ...r, ...s]);
}

export async function createTestPasskey(): Promise<{ id: string; publicKey: Uint8Array; jwk: JsonWebKey }> {
  const kp = await crypto.subtle.generateKey({ name: "ECDSA", namedCurve: "P-256" }, true, ["sign", "verify"]);
  const publicKey = new Uint8Array(await crypto.subtle.exportKey("raw", kp.publicKey)); // 0x04||X||Y
  const jwk = await crypto.subtle.exportKey("jwk", kp.privateKey);
  return { id: "test-passkey", publicKey, jwk };
}

export async function testAssertion(jwk: JsonWebKey, challenge: Uint8Array, rpId: string, origin: string): Promise<Assertion> {
  const key = await crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
  const sha = async (b: Uint8Array) => new Uint8Array(await crypto.subtle.digest("SHA-256", b as BufferSource));
  const counter = Math.floor(Date.now() / 1000);
  const authenticatorData = new Uint8Array([...(await sha(new TextEncoder().encode(rpId))), 0x05,
    (counter >>> 24) & 255, (counter >>> 16) & 255, (counter >>> 8) & 255, counter & 255]);
  const clientDataJSON = new TextEncoder().encode(JSON.stringify({ type: "webauthn.get", challenge: b64u(challenge), origin, crossOrigin: false }));
  const msg = new Uint8Array([...authenticatorData, ...(await sha(clientDataJSON))]);
  const raw = new Uint8Array(await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, msg as BufferSource));
  return { authenticatorData, clientDataJSON, signature: rawToDer(raw) };
}
